package server

// Documentation page (documentation.html) — the in-app illustrated user guide.
// Content localized AZ/EN/RU. HTML tags inside values are intentional (the t
// helper returns template.HTML), so inline <b>/<code> render as markup.
func init() {
	addMessages(map[string]map[string]string{
		"doc.title":       {"az": "PROPhish — İstifadə Təlimatı", "en": "PROPhish — User Guide", "ru": "PROPhish — Руководство пользователя"},
		"doc.intro":       {"az": "Bu təlimat platformanın bütün funksiyalarını ilk quraşdırmadan kampaniya nəticələrinə qədər addım-addım izah edir. Hər bölmədə müvafiq ekranın görüntüsü və nə etməli olduğunuz göstərilir. PROPhish icazəli (authorized) təhlükəsizlik maarifləndirmə simulyasiyaları üçündür — parollar heç vaxt saxlanılmır, yalnız davranış faktı (açdı / klik etdi / göndərdi / bildirdi) qeyd olunur.", "en": "This guide explains every feature of the platform step by step, from initial setup to campaign results. Each section shows a screenshot of the relevant screen and what you need to do. PROPhish is intended for authorized security-awareness simulations — passwords are never stored; only the behavioral fact (opened / clicked / submitted / reported) is recorded.", "ru": "Это руководство шаг за шагом объясняет все функции платформы — от первоначальной настройки до результатов кампаний. В каждом разделе показан снимок соответствующего экрана и то, что вам нужно сделать. PROPhish предназначен для авторизованных (authorized) симуляций по повышению осведомлённости в области безопасности — пароли никогда не сохраняются, фиксируется только факт поведения (открыл / кликнул / отправил / сообщил)."},
		"doc.s1_title":    {"az": "İlk quraşdırma", "en": "Initial setup", "ru": "Первоначальная настройка"},
		"doc.s1_p":        {"az": "Platforma ilk dəfə açılanda sizi quraşdırma ekranına yönləndirir. Burada ilk <b>administrator</b> hesabını yaradırsınız. Bu hesab bütün idarəetmə hüquqlarına malikdir və sonradan başqa operatorlar əlavə edə bilər.", "en": "The first time the platform is opened, it redirects you to the setup screen. Here you create the first <b>administrator</b> account. This account has all management rights and can later add other operators.", "ru": "При первом запуске платформа перенаправляет вас на экран настройки. Здесь вы создаёте первую учётную запись <b>администратора</b>. Эта учётная запись обладает всеми правами управления и впоследствии может добавлять других операторов."},
		"doc.s1_1":        {"az": "E-poçt ünvanınızı daxil edin (giriş üçün istifadə olunacaq).", "en": "Enter your email address (it will be used for login).", "ru": "Введите ваш адрес электронной почты (будет использоваться для входа)."},
		"doc.s1_2":        {"az": "Güclü bir parol təyin edin — parol yalnız bcrypt hash kimi saxlanılır, açıq mətn kimi heç vaxt.", "en": "Set a strong password — the password is stored only as a bcrypt hash, never as plain text.", "ru": "Задайте надёжный пароль — пароль хранится только в виде bcrypt-хеша, никогда в виде открытого текста."},
		"doc.s1_3":        {"az": "<b>Hesabı yarat</b> düyməsini basın — avtomatik daxil olursunuz.", "en": "Click the <b>Create account</b> button — you will be logged in automatically.", "ru": "Нажмите кнопку <b>Создать учётную запись</b> — вы автоматически войдёте в систему."},
		"doc.s1_cap":      {"az": "İlk administrator hesabının yaradılması", "en": "Creating the first administrator account", "ru": "Создание первой учётной записи администратора"},
		"doc.s2_title":    {"az": "Giriş", "en": "Login", "ru": "Вход"},
		"doc.s2_p":        {"az": "Administrator hesabı yaradıldıqdan sonra platforma sizi giriş ekranı ilə qarşılayır. E-poçt və parolla daxil olursunuz. Sağ yuxarıda tema (açıq/tünd) və dil (AZ / EN / RU) seçimi var.", "en": "After the administrator account is created, the platform greets you with the login screen. You log in with your email and password. In the top right there is a theme (light/dark) and language (AZ / EN / RU) selector.", "ru": "После создания учётной записи администратора платформа встречает вас экраном входа. Вы входите с помощью электронной почты и пароля. В правом верхнем углу есть выбор темы (светлая/тёмная) и языка (AZ / EN / RU)."},
		"doc.s2_cap":      {"az": "Operator giriş ekranı", "en": "Operator login screen", "ru": "Экран входа оператора"},
		"doc.s2_note":     {"az": "Admin paneli artıq birbaşa açıla bilər (SSH tunel məcburi deyil), lakin onu <code>PROPHISH_ADMIN_ALLOW_CIDRS</code> <b>IP ağ siyahısı</b> ilə yalnız etibarlı şəbəkələrə bağlayın (məs. <code>10.0.0.0/8</code>). Siyahı boş olarsa məhdudiyyət yoxdur; loopback həmişə buraxılır. Yoxlama birbaşa qoşulmanın IP-sini istifadə edir — <code>X-Forwarded-For</code> başlığına etibar edilmir, ona görə onu başlıqla saxtalaşdırmaq olmaz. Docker arxasında konteyner həqiqi müştəri IP-sini görməlidir (əks halda bütün müştərilər şlüz kimi görünür) — buna görə onu host firewall ilə birlikdə istifadə edin.", "en": "The admin panel can now be reached directly (no SSH tunnel required), but lock it to trusted networks with the <code>PROPHISH_ADMIN_ALLOW_CIDRS</code> <b>IP allowlist</b> (e.g. <code>10.0.0.0/8</code>). An empty list means no restriction; loopback is always allowed. The check uses the direct connection IP — <code>X-Forwarded-For</code> is not trusted, so it cannot be spoofed with a header. Behind Docker the container must see the real client IP (otherwise every client looks like the gateway) — so pair it with a host firewall.", "ru": "Панель администратора теперь можно открывать напрямую (SSH-туннель не обязателен), но ограничьте её доверенными сетями с помощью <b>IP-белого списка</b> <code>PROPHISH_ADMIN_ALLOW_CIDRS</code> (напр. <code>10.0.0.0/8</code>). Пустой список означает отсутствие ограничений; loopback разрешён всегда. Проверка использует IP прямого подключения — заголовку <code>X-Forwarded-For</code> нет доверия, поэтому его нельзя подделать заголовком. За Docker контейнер должен видеть реальный IP клиента (иначе все клиенты выглядят как шлюз) — поэтому сочетайте это с файрволом на хосте."},
		"doc.s3_title":    {"az": "Nəzarət paneli", "en": "Dashboard", "ru": "Панель управления"},
		"doc.s3_p":        {"az": "Daxil olduqda ilk gördüyünüz ekran. Yuxarıda dörd əsas göstərici var: <b>aktiv kampaniyalar</b>, <b>test olunmuş işçilər</b>, <b>orta klik faizi</b> (aşağı = daha yaxşı) və <b>phishing bildirmə faizi</b> (yüksək = daha yaxşı). Aşağıda son kampaniyalar siyahısı göstərilir.", "en": "The first screen you see after logging in. At the top there are four key metrics: <b>active campaigns</b>, <b>employees tested</b>, <b>average click rate</b> (lower = better) and <b>phishing report rate</b> (higher = better). Below, the list of recent campaigns is shown.", "ru": "Экран, который вы видите первым после входа. Вверху четыре основных показателя: <b>активные кампании</b>, <b>протестированные сотрудники</b>, <b>средний процент кликов</b> (ниже = лучше) и <b>процент сообщений о фишинге</b> (выше = лучше). Ниже отображается список последних кампаний."},
		"doc.s3_cap":      {"az": "Nəzarət paneli — ümumi göstəricilər və son kampaniyalar", "en": "Dashboard — overall metrics and recent campaigns", "ru": "Панель управления — общие показатели и последние кампании"},
		"doc.s3_h_del":    {"az": "Toplu silmə", "en": "Bulk deletion", "ru": "Массовое удаление"},
		"doc.s3_del":      {"az": "Son kampaniyalar cədvəlində hər sətrin solunda və başlıqda checkbox var. Tək-tək və ya <b>hamısını seç</b> ilə seçib <b>Seçilənləri sil</b> düyməsi ilə silə bilərsiniz (təsdiqdən sonra). Silinən kampaniyanın bütün nəticələri də silinir.", "en": "In the recent campaigns table there is a checkbox to the left of each row and in the header. You can select rows one by one or with <b>Select all</b> and delete them with the <b>Delete selected</b> button (after confirmation). All results of a deleted campaign are also deleted.", "ru": "В таблице последних кампаний слева от каждой строки и в заголовке есть флажок. Вы можете выбрать по одному или с помощью <b>выбрать все</b> и удалить кнопкой <b>Удалить выбранные</b> (после подтверждения). Все результаты удалённой кампании также удаляются."},
		"doc.s3_nav":      {"az": "Soldakı panel bütün bölmələrə keçid verir: <b>İş sahəsi</b> (Nəzarət paneli, Kampaniyalar), <b>Qurğu</b> (Müştərilər, Şablonlar, Səhifələr, Kitabxana, SMTP profilləri) və <b>Admin</b> (İstifadəçilər, Parametrlər, Audit jurnalı).", "en": "The panel on the left provides navigation to all sections: <b>Workspace</b> (Dashboard, Campaigns), <b>Setup</b> (Clients, Templates, Pages, Library, SMTP profiles) and <b>Admin</b> (Users, Settings, Audit log).", "ru": "Панель слева даёт переход ко всем разделам: <b>Рабочая область</b> (Панель управления, Кампании), <b>Настройка</b> (Клиенты, Шаблоны, Страницы, Библиотека, SMTP-профили) и <b>Admin</b> (Пользователи, Настройки, Журнал аудита)."},
		"doc.s4_title":    {"az": "Müştərilər və icazələr", "en": "Clients and authorizations", "ru": "Клиенты и авторизации"},
		"doc.s4_p":        {"az": "Hər kampaniya bir <b>müştəriyə</b> bağlıdır (öz təşkilatınız və ya xidmət göstərdiyiniz şirkət). Müştəri yaratdıqdan sonra onun səhifəsində <b>icazə (authorization / RoE)</b> əlavə etməlisiniz — bu, hüquqi qapıdır: kampaniya yalnız qüvvədə olan icazə varsa işə salına bilər.", "en": "Each campaign is tied to a <b>client</b> (your own organization or a company you provide services to). After creating a client, you must add an <b>authorization (authorization / RoE)</b> on its page — this is the legal gate: a campaign can only be launched if there is a valid authorization.", "ru": "Каждая кампания привязана к <b>клиенту</b> (ваша собственная организация или компания, которую вы обслуживаете). После создания клиента на его странице необходимо добавить <b>авторизацию (authorization / RoE)</b> — это юридический барьер: кампанию можно запустить только при наличии действующей авторизации."},
		"doc.s4_1":        {"az": "<b>Müştərilər</b> bölməsində yeni müştəri yaradın (ad, əlaqə e-poçtu, qeydlər).", "en": "In the <b>Clients</b> section, create a new client (name, contact email, notes).", "ru": "В разделе <b>Клиенты</b> создайте нового клиента (имя, контактный e-mail, заметки)."},
		"doc.s4_2":        {"az": "Müştərinin səhifəsində <b>icazə</b> əlavə edin: əhatə dairəsi (məs. <code>*.şirkət.az</code>), icazə verən şəxs, sənəd nömrəsi və qüvvədə olma tarixləri.", "en": "On the client's page, add an <b>authorization</b>: scope (e.g. <code>*.company.com</code>), the person granting authorization, document number and validity dates.", "ru": "На странице клиента добавьте <b>авторизацию</b>: область охвата (напр. <code>*.company.ru</code>), лицо, выдавшее разрешение, номер документа и сроки действия."},
		"doc.s4_3":        {"az": "Həmçinin bu səhifədə həmin müştəri üçün <b>qruplar</b> yaradırsınız.", "en": "On this page you also create <b>groups</b> for that client.", "ru": "Также на этой странице вы создаёте <b>группы</b> для данного клиента."},
		"doc.s4_cap1":     {"az": "Müştərilər siyahısı", "en": "Clients list", "ru": "Список клиентов"},
		"doc.s4_cap2":     {"az": "Müştəri səhifəsi — icazələr və qruplar", "en": "Client page — authorizations and groups", "ru": "Страница клиента — авторизации и группы"},
		"doc.s4_note":     {"az": "İcazə olmadan və ya icazənin müddəti bitmişsə kampaniya işə salınmır — bu, sistemin qəsdən qoyulmuş qoruyucusudur.", "en": "Without an authorization, or if the authorization has expired, a campaign cannot be launched — this is a deliberate safeguard built into the system.", "ru": "Без авторизации или при истёкшем сроке её действия кампания не запускается — это намеренно заложенный предохранитель системы."},
		"doc.s5_title":    {"az": "Qruplar və hədəflər", "en": "Groups and targets", "ru": "Группы и цели"},
		"doc.s5_p":        {"az": "Qrup — birlikdə test ediləcək işçilərin siyahısıdır (məs. \"Maliyyə Departamenti\"). Qrupun səhifəsində hədəfləri tək-tək və ya <b>CSV</b> ilə toplu əlavə edirsiniz.", "en": "A group is a list of employees to be tested together (e.g. \"Finance Department\"). On the group's page, you add targets one by one or in bulk via <b>CSV</b>.", "ru": "Группа — это список сотрудников, которые будут протестированы вместе (напр. «Финансовый департамент»). На странице группы вы добавляете цели по одной или массово с помощью <b>CSV</b>."},
		"doc.s5_1":        {"az": "Qrupu açın və hədəf əlavə edin: e-poçt, ad, soyad, vəzifə.", "en": "Open the group and add a target: email, first name, last name, position.", "ru": "Откройте группу и добавьте цель: e-mail, имя, фамилия, должность."},
		"doc.s5_2":        {"az": "Çoxlu hədəf üçün CSV faylı yükləyin.", "en": "For multiple targets, upload a CSV file.", "ru": "Для множества целей загрузите CSV-файл."},
		"doc.s5_cap":      {"az": "Qrup səhifəsi — hədəflərin idarə olunması", "en": "Group page — managing targets", "ru": "Страница группы — управление целями"},
		"doc.s6_title":    {"az": "E-poçt şablonları", "en": "Email templates", "ru": "Шаблоны писем"},
		"doc.s6_p":        {"az": "Hədəflərə göndəriləcək fişinq e-poçtunun məzmunu. Şablonda mövzu və HTML gövdə olur. Linkləri izləmək üçün <code>{{.TrackingURL}}</code> dəyişənindən istifadə edin — sistem onu hər hədəf üçün unikal izləmə linki ilə əvəz edir.", "en": "The content of the phishing email that will be sent to the targets. A template has a subject and an HTML body. To track links, use the <code>{{.TrackingURL}}</code> variable — the system replaces it with a unique tracking link for each target.", "ru": "Содержимое фишингового письма, которое будет отправлено целям. Шаблон содержит тему и HTML-тело. Для отслеживания ссылок используйте переменную <code>{{.TrackingURL}}</code> — система заменяет её уникальной для каждой цели ссылкой отслеживания."},
		"doc.s6_cap":      {"az": "E-poçt şablonları", "en": "Email templates", "ru": "Шаблоны писем"},
		"doc.s7_title":    {"az": "Açılış səhifələri", "en": "Landing pages", "ru": "Целевые страницы"},
		"doc.s7_p":        {"az": "İşçi linkə klikləyəndən sonra gördüyü səhifə (məs. saxta giriş səhifəsi). Üç yolla yarada bilərsiniz:", "en": "The page an employee sees after clicking the link (e.g. a fake login page). You can create it in three ways:", "ru": "Страница, которую сотрудник видит после клика по ссылке (напр. поддельная страница входа). Создать её можно тремя способами:"},
		"doc.s7_1":        {"az": "<b>URL-dən klonla</b> — mövcud bir səhifəni çəkib açılış səhifəsinə çevirir; formalar avtomatik izlənməyə yönəldilir.", "en": "<b>Clone from URL</b> — fetches an existing page and turns it into a landing page; forms are automatically redirected to tracking.", "ru": "<b>Клонировать из URL</b> — загружает существующую страницу и превращает её в целевую; формы автоматически перенаправляются на отслеживание."},
		"doc.s7_2":        {"az": "<b>Əl ilə</b> — HTML gövdəni özünüz yazırsınız. Forma <code>action=\"{{.SubmitURL}}\"</code> və <code>method=\"post\"</code> olmalıdır.", "en": "<b>Manual</b> — you write the HTML body yourself. The form must be <code>action=\"{{.SubmitURL}}\"</code> and <code>method=\"post\"</code>.", "ru": "<b>Вручную</b> — вы сами пишете HTML-тело. Форма должна иметь <code>action=\"{{.SubmitURL}}\"</code> и <code>method=\"post\"</code>."},
		"doc.s7_3":        {"az": "<b>Vizual redaktor</b> və ya <b>Kitabxana</b> (aşağıda).", "en": "<b>Visual editor</b> or <b>Library</b> (below).", "ru": "<b>Визуальный редактор</b> или <b>Библиотека</b> (ниже)."},
		"doc.s7_cap":      {"az": "Açılış səhifələri", "en": "Landing pages", "ru": "Целевые страницы"},
		"doc.s7_note":     {"az": "Təhlükəsizlik: daxil edilən parollar <b>heç vaxt oxunmur və saxlanılmır</b> — yalnız formanın göndərildiyi faktı qeyd olunur.", "en": "Security: entered passwords are <b>never read or stored</b> — only the fact that the form was submitted is recorded.", "ru": "Безопасность: введённые пароли <b>никогда не читаются и не сохраняются</b> — фиксируется только факт отправки формы."},
		"doc.s8_title":    {"az": "Vizual redaktor", "en": "Visual editor", "ru": "Визуальный редактор"},
		"doc.s8_p":        {"az": "HTML bilmədən açılış səhifəsini sürükle-burax üsulu ilə yaratmaq üçün. Hazır bloklar, mətn, şəkil, forma elementləri əlavə edib dizaynı birbaşa görərək qurursunuz.", "en": "For building a landing page by drag-and-drop, without knowing HTML. You add ready-made blocks, text, images and form elements and build the design while seeing it directly.", "ru": "Для создания целевой страницы методом перетаскивания без знания HTML. Вы добавляете готовые блоки, текст, изображения, элементы форм и строите дизайн, сразу видя результат."},
		"doc.s8_cap":      {"az": "Vizual səhifə redaktoru", "en": "Visual page editor", "ru": "Визуальный редактор страниц"},
		"doc.s9_title":    {"az": "Kitabxana", "en": "Library", "ru": "Библиотека"},
		"doc.s9_p":        {"az": "Hazır brend şablonları — Microsoft 365, Google, OneDrive, OWA, IT parol portalı və s. Sıfırdan yazmaq istəmirsinizsə, kitabxanadan hazır bir dəsti (e-poçt + açılış səhifəsi) seçib bir kliklə istifadəyə alırsınız.", "en": "Ready-made brand templates — Microsoft 365, Google, OneDrive, OWA, IT password portal, etc. If you do not want to write from scratch, you select a ready-made set (email + landing page) from the library and put it to use with one click.", "ru": "Готовые брендовые шаблоны — Microsoft 365, Google, OneDrive, OWA, портал смены паролей IT и т. д. Если вы не хотите создавать с нуля, выберите из библиотеки готовый набор (письмо + целевая страница) и задействуйте его в один клик."},
		"doc.s9_cap":      {"az": "Hazır şablon kitabxanası", "en": "Ready-made template library", "ru": "Библиотека готовых шаблонов"},
		"doc.s10_title":   {"az": "SMTP profilləri", "en": "SMTP profiles", "ru": "SMTP-профили"},
		"doc.s10_p":       {"az": "E-poçtların hansı poçt serveri ilə göndəriləcəyini təyin edir: SMTP host, port, istifadəçi, \"From\" ünvanı. SMTP parolu şifrələnmiş saxlanılır (açıq mətn kimi yox).", "en": "Defines which mail server emails are sent through: SMTP host, port, user, \"From\" address. The SMTP password is stored encrypted (not as plain text).", "ru": "Определяет, через какой почтовый сервер будут отправляться письма: SMTP host, port, пользователь, адрес \"From\". Пароль SMTP хранится в зашифрованном виде (не в виде открытого текста)."},
		"doc.s10_cap":     {"az": "Göndərmə (SMTP) profilləri", "en": "Sending (SMTP) profiles", "ru": "Профили отправки (SMTP)"},
		"doc.s10_note":    {"az": "Test üçün daxili MailHog serverindən istifadə edə bilərsiniz (host <code>mailhog</code>, port <code>1025</code>).", "en": "For testing you can use the built-in MailHog server (host <code>mailhog</code>, port <code>1025</code>).", "ru": "Для тестирования можно использовать встроенный сервер MailHog (host <code>mailhog</code>, порт <code>1025</code>)."},
		"doc.s11_title":   {"az": "Kampaniya yaratmaq", "en": "Creating a campaign", "ru": "Создание кампании"},
		"doc.s11_p":       {"az": "Bütün komponentləri birləşdirən addım. Kampaniya forması: ad, müştəri, icazə, qrup(lar), e-poçt şablonu, açılış səhifəsi və SMTP profili seçirsiniz. Ən vacib hissə — <b>Listener</b> (hədəflərin linkə haradan çatacağı) seçimidir.", "en": "The step that brings all the components together. In the campaign form you select: name, client, authorization, group(s), email template, landing page and SMTP profile. The most important part is the <b>Listener</b> (where the targets will reach the link from) selection.", "ru": "Шаг, объединяющий все компоненты. Форма кампании: вы выбираете имя, клиента, авторизацию, группу(ы), шаблон письма, целевую страницу и SMTP-профиль. Самая важная часть — выбор <b>Listener</b> (откуда цели будут обращаться к ссылке)."},
		"doc.s11_cap":     {"az": "Kampaniya yaratma forması və listener seçimləri", "en": "Campaign creation form and listener options", "ru": "Форма создания кампании и варианты listener"},
		"doc.s11_h_modes": {"az": "Listener rejimləri", "en": "Listener modes", "ru": "Режимы Listener"},
		"doc.s11_m1_t":    {"az": "Hazırki host", "en": "Current host", "ru": "Текущий хост"},
		"doc.s11_m1_pill": {"az": "daxili / LAN", "en": "internal / LAN", "ru": "внутренний / LAN"},
		"doc.s11_m1_d":    {"az": "Linklər birbaşa bu serverin ünvanına işarə edir. Yalnız hədəflər həmin ünvana çata bildikdə (korporativ şəbəkə daxilində) işləyir. Public IP yoxdursa xaricdən açılmaz.", "en": "Links point directly to this server's address. It works only when the targets can reach that address (within the corporate network). If there is no public IP, it cannot be opened from outside.", "ru": "Ссылки указывают напрямую на адрес этого сервера. Работает только если цели могут достичь этого адреса (внутри корпоративной сети). Без публичного IP извне не откроется."},
		"doc.s11_m2_t":    {"az": "Cloudflare gateway", "en": "Cloudflare gateway", "ru": "Cloudflare gateway"},
		"doc.s11_m2_pill": {"az": "tövsiyə / hər yerdən", "en": "recommended / from anywhere", "ru": "рекомендуется / отовсюду"},
		"doc.s11_m2_d":    {"az": "Hər kampaniya üçün avtomatik <code>https://…trycloudflare.com</code> tuneli açılır. Hədəf linki ev, telefon, istənilən yerdən aça bilir və bağlantı HTTPS-dir. Yalnız serverdən çıxış (outbound) internet lazımdır.", "en": "An <code>https://…trycloudflare.com</code> tunnel is opened automatically for each campaign. The target can open the link from home, a phone, anywhere, and the connection is HTTPS. Only outbound internet from the server is required.", "ru": "Для каждой кампании автоматически открывается туннель <code>https://…trycloudflare.com</code>. Цель может открыть ссылку из дома, с телефона, из любого места, и соединение идёт по HTTPS. Нужен только исходящий (outbound) интернет с сервера."},
		"doc.s11_m3_t":    {"az": "Xüsusi URL", "en": "Custom URL", "ru": "Пользовательский URL"},
		"doc.s11_m3_pill": {"az": "öz domeniniz", "en": "your own domain", "ru": "ваш домен"},
		"doc.s11_m3_d":    {"az": "Öz domeniniz və ya reverse proxy-niz varsa, tam URL-i əl ilə daxil edirsiniz (məs. <code>https://secure.domeniniz.az</code>).", "en": "If you have your own domain or reverse proxy, you enter the full URL manually (e.g. <code>https://secure.domeniniz.az</code>).", "ru": "Если у вас есть собственный домен или reverse proxy, вы вводите полный URL вручную (напр. <code>https://secure.domeniniz.az</code>)."},
		"doc.s11_note":    {"az": "Cloudflare gateway seçsəniz, tunel URL-i hazır olana qədər (~5-10 san) sistem göndərişi gözləyir — tez göndərsəniz belə linklər düzgün olur. Kampaniya göndərildikdən sonra serveri restart etməyin, əks halda tunel URL-i dəyişər.", "en": "If you choose the Cloudflare gateway, the system waits to send until the tunnel URL is ready (~5-10 sec) — so even if you send quickly, the links will be correct. Do not restart the server after the campaign has been sent, otherwise the tunnel URL will change.", "ru": "Если вы выберете Cloudflare gateway, система ждёт с отправкой, пока URL туннеля не будет готов (~5-10 сек) — даже при быстрой отправке ссылки получаются корректными. После отправки кампании не перезапускайте сервер, иначе URL туннеля изменится."},
		"doc.s12_title":   {"az": "Nəticələr və hesabat", "en": "Results and reporting", "ru": "Результаты и отчёт"},
		"doc.s12_p":       {"az": "Kampaniya işə salındıqdan sonra detal səhifəsində real nəticələri izləyirsiniz: neçə nəfərə <b>göndərildi</b>, neçəsi <b>açdı</b>, <b>klik etdi</b>, <b>məlumat verdi</b> və <b>phishing kimi bildirdi</b>. Sağda ümumi <b>risk balı</b> (Aşağı / Orta / Yüksək) göstərilir.", "en": "After the campaign is launched, you track the real results on the detail page: how many it was <b>sent</b> to, how many <b>opened</b>, <b>clicked</b>, <b>submitted data</b> and <b>reported as phishing</b>. On the right, an overall <b>risk score</b> (Low / Medium / High) is shown.", "ru": "После запуска кампании на странице её деталей вы отслеживаете реальные результаты: скольким <b>отправлено</b>, сколько <b>открыло</b>, <b>кликнуло</b>, <b>ввело данные</b> и <b>сообщило о фишинге</b>. Справа отображается общий <b>балл риска</b> (Низкий / Средний / Высокий)."},
		"doc.s12_cap":     {"az": "Kampaniya detalı — davranış icmalı və risk balı", "en": "Campaign detail — behavior summary and risk score", "ru": "Детали кампании — обзор поведения и балл риска"},
		"doc.s12_1":       {"az": "<b>Yenilə</b> — nəticələri yeniləyir (tamamlanmış kampaniyalar avtomatik yenilənmir).", "en": "<b>Refresh</b> — refreshes the results (completed campaigns are not refreshed automatically).", "ru": "<b>Обновить</b> — обновляет результаты (завершённые кампании не обновляются автоматически)."},
		"doc.s12_2":       {"az": "<b>PDF hesabat</b> — rəhbərliyə təqdim üçün hesabat.", "en": "<b>PDF report</b> — a report to present to management.", "ru": "<b>PDF-отчёт</b> — отчёт для представления руководству."},
		"doc.s12_3":       {"az": "<b>CSV export</b> — hədəf-səviyyəli nəticələr.", "en": "<b>CSV export</b> — target-level results.", "ru": "<b>CSV-экспорт</b> — результаты на уровне целей."},
		"doc.s12_note":    {"az": "\"Açıldı\" piksel-əsaslıdır — bəzi poçt sistemləri şəkilləri bloklayır (açılma az görünə bilər) və ya linkləri avtomatik yoxlayır (açılma/klik şişə bilər).", "en": "\"Opened\" is pixel-based — some mail systems block images (opens may appear lower) or automatically check links (opens/clicks may be inflated).", "ru": "«Открыто» основано на пикселе — некоторые почтовые системы блокируют изображения (открытия могут выглядеть заниженными) или автоматически проверяют ссылки (открытия/клики могут быть завышены)."},
		"doc.s13_title":   {"az": "İstifadəçilər", "en": "Users", "ru": "Пользователи"},
		"doc.s13_p":       {"az": "Admin bölməsində əlavə operatorlar yarada, rolları (admin / operator) təyin edə və hesabları aktiv/deaktiv edə bilərsiniz.", "en": "In the Admin section you can create additional operators, assign roles (admin / operator) and activate/deactivate accounts.", "ru": "В разделе Admin вы можете создавать дополнительных операторов, назначать роли (admin / operator) и активировать/деактивировать учётные записи."},
		"doc.s13_cap":     {"az": "İstifadəçilərin idarə olunması", "en": "Managing users", "ru": "Управление пользователями"},
		"doc.s14_title":   {"az": "Parametrlər (IMAP)", "en": "Settings (IMAP)", "ru": "Настройки (IMAP)"},
		"doc.s14_p":       {"az": "Phishing-bildirmə qutusunu (işçilərin şübhəli e-poçtu yönləndirdiyi IMAP qutusu) konfiqurasiya edirsiniz. Sistem bu qutunu yoxlayıb hədəfləri avtomatik \"bildirdi\" kimi işarələyir — bu, müsbət göstəricidir.", "en": "You configure the phishing-report mailbox (the IMAP mailbox to which employees forward suspicious emails). The system checks this mailbox and automatically marks targets as \"reported\" — this is a positive metric.", "ru": "Вы настраиваете ящик для сообщений о фишинге (IMAP-ящик, куда сотрудники пересылают подозрительные письма). Система проверяет этот ящик и автоматически помечает цели как \"сообщил\" — это положительный показатель."},
		"doc.s14_cap":     {"az": "IMAP / phishing-bildirmə parametrləri", "en": "IMAP / phishing-report settings", "ru": "Параметры IMAP / сообщений о фишинге"},

		// ---- Confirmation modal (Dashboard section) ----
		"doc.s3_confirm_note": {"az": "Bütün silmə və digər dağıdıcı əməliyyatlar artıq mərkəzi <b>təsdiq pəncərəsi</b> ilə qorunur: <b>Bəli</b> / <b>Xeyr</b> düymələri və bağlama (✕) işarəsi olur. <b>Xeyr</b>, ✕, fonun boş sahəsinə klik və ya <b>Esc</b> əməliyyatı ləğv edir; yalnız <b>Bəli</b> onu icra edir. Bu, təsadüfi kliklərə qarşı qoruyucudur.", "en": "All deletions and other destructive actions are now protected by a centred <b>confirmation dialog</b>: it has <b>Yes</b> / <b>No</b> buttons and a close (✕) icon. <b>No</b>, the ✕, a click on the backdrop or <b>Esc</b> cancels the action; only <b>Yes</b> carries it out. This is a safeguard against accidental clicks.", "ru": "Все удаления и другие разрушительные действия теперь защищены центральным <b>окном подтверждения</b>: в нём есть кнопки <b>Да</b> / <b>Нет</b> и значок закрытия (✕). <b>Нет</b>, ✕, клик по фону или <b>Esc</b> отменяют действие; выполняет его только <b>Да</b>. Это защита от случайных кликов."},
		"doc.confirm_cap":     {"az": "Təsdiq pəncərəsi silmədən əvvəl soruşur (nümunə: müştəri silmə).", "en": "The confirmation dialog asks before deleting (example: deleting a client).", "ru": "Окно подтверждения спрашивает перед удалением (пример: удаление клиента)."},

		// ---- Bulk deletion on the Clients / Templates / Pages list pages ----
		"doc.s4_h_bulk":    {"az": "Toplu silmə", "en": "Bulk deletion", "ru": "Массовое удаление"},
		"doc.s4_bulk":      {"az": "Müştərilər siyahısında hər sətrin solunda və başlıqda checkbox var. Tək-tək və ya <b>hamısını seç</b> ilə seçib <b>Seçilənləri sil</b> düyməsi ilə silirsiniz (təsdiq pəncərəsindən sonra). Diqqət: müştərinin silinməsi <b>kaskad</b>dır — onunla birlikdə həmin müştəriyə aid bütün icazələr, qruplar və hədəflər, müştəriyə bağlı şablon və səhifələr, həmçinin kampaniyalar və onların nəticələri silinir. Yalnız müştəriyə bağlı obyektlər təsir alır; <b>qlobal (paylaşılan) şablon və səhifələr</b> toxunulmur.", "en": "In the Clients list there is a checkbox to the left of each row and in the header. You select rows one by one or with <b>Select all</b> and delete them with the <b>Delete selected</b> button (after the confirmation dialog). Note: deleting a client is a <b>cascade</b> — it also removes all of that client's authorizations, groups and targets, its client-scoped templates and pages, and its campaigns together with their results. Only objects tied to the client are affected; <b>global (shared) templates and pages</b> are left untouched.", "ru": "В списке клиентов слева от каждой строки и в заголовке есть флажок. Вы выбираете по одному или с помощью <b>выбрать все</b> и удаляете кнопкой <b>Удалить выбранные</b> (после окна подтверждения). Внимание: удаление клиента — <b>каскадное</b>: вместе с ним удаляются все авторизации, группы и цели этого клиента, привязанные к нему шаблоны и страницы, а также кампании и их результаты. Затрагиваются только объекты, привязанные к клиенту; <b>глобальные (общие) шаблоны и страницы</b> не затрагиваются."},
		"doc.s4_bulk_note": {"az": "Silinmə <b>geri qaytarıla bilməz</b>. Əgər müştərinin şablonu və ya səhifəsi <b>başqa müştərinin</b> kampaniyasında istifadə olunursa, həmin müştəri bütövlükdə silinmir (digər seçilmiş müştərilər silinir). Qeyd: tək-tək silmə admin tələb etsə də, toplu silmə istənilən daxil olmuş operator üçün əlçatandır.", "en": "Deletion is <b>irreversible</b>. If a client's template or page is still used by <b>another client's</b> campaign, that client is not deleted at all (the other selected clients still are). Note: although single-item deletion requires an admin, bulk deletion is available to any logged-in operator.", "ru": "Удаление <b>необратимо</b>. Если шаблон или страница клиента всё ещё используется в кампании <b>другого клиента</b>, этот клиент не удаляется целиком (остальные выбранные клиенты удаляются). Примечание: хотя удаление по одному требует роли admin, массовое удаление доступно любому вошедшему оператору."},
		"doc.s6_h_bulk":    {"az": "Toplu silmə", "en": "Bulk deletion", "ru": "Массовое удаление"},
		"doc.s6_bulk":      {"az": "Şablonlar siyahısında hər sətrin solunda və başlıqda checkbox var. Tək-tək və ya <b>hamısını seç</b> ilə seçib <b>Seçilənləri sil</b> düyməsi ilə silirsiniz (təsdiqdən sonra). Hələ də bir kampaniyada <b>istifadə olunan</b> şablon silinmir — həmin sətir yerində qalır, qalan seçilmiş şablonlar isə silinir. Bu halda sistem neçəsinin silindiyini və neçəsinin istifadədə olduğunu bildirir.", "en": "In the Templates list there is a checkbox to the left of each row and in the header. You select rows one by one or with <b>Select all</b> and delete them with the <b>Delete selected</b> button (after confirmation). A template still <b>in use</b> by a campaign is not deleted — that row stays in place, while the rest of the selected templates are deleted. In this case the system reports how many were deleted and how many are in use.", "ru": "В списке шаблонов слева от каждой строки и в заголовке есть флажок. Вы выбираете по одному или с помощью <b>выбрать все</b> и удаляете кнопкой <b>Удалить выбранные</b> (после подтверждения). Шаблон, всё ещё <b>используемый</b> кампанией, не удаляется — эта строка остаётся на месте, а остальные выбранные шаблоны удаляются. В этом случае система сообщает, сколько удалено и сколько используется."},
		"doc.s7_h_bulk":    {"az": "Toplu silmə", "en": "Bulk deletion", "ru": "Массовое удаление"},
		"doc.s7_bulk":      {"az": "Səhifələr siyahısında hər sətrin solunda və başlıqda checkbox var. Tək-tək və ya <b>hamısını seç</b> ilə seçib <b>Seçilənləri sil</b> düyməsi ilə silirsiniz (təsdiqdən sonra). Hələ də bir kampaniyada <b>istifadə olunan</b> açılış səhifəsi silinmir — həmin sətir qalır, qalan seçilmişlər silinir və sistem nəticəni (neçəsi silindi / neçəsi istifadədə) göstərir.", "en": "In the Pages list there is a checkbox to the left of each row and in the header. You select rows one by one or with <b>Select all</b> and delete them with the <b>Delete selected</b> button (after confirmation). A landing page still <b>in use</b> by a campaign is not deleted — that row stays, the rest of the selected ones are deleted, and the system shows the result (how many deleted / how many in use).", "ru": "В списке страниц слева от каждой строки и в заголовке есть флажок. Вы выбираете по одному или с помощью <b>выбрать все</b> и удаляете кнопкой <b>Удалить выбранные</b> (после подтверждения). Целевая страница, всё ещё <b>используемая</b> кампанией, не удаляется — эта строка остаётся, остальные выбранные удаляются, а система показывает результат (сколько удалено / сколько используется)."},

		"doc.workflow": {"az": "<b>Tam iş axını:</b> Müştəri yarat → icazə əlavə et → qrup və hədəflər → e-poçt şablonu → açılış səhifəsi → SMTP profili → kampaniya yarat (listener seç) → işə sal → nəticələri izlə → PDF/CSV hesabat.", "en": "<b>Full workflow:</b> Create client → add authorization → group and targets → email template → landing page → SMTP profile → create campaign (select listener) → launch → track results → PDF/CSV report.", "ru": "<b>Полный рабочий процесс:</b> Создать клиента → добавить авторизацию → группа и цели → шаблон письма → целевая страница → SMTP-профиль → создать кампанию (выбрать listener) → запустить → отслеживать результаты → PDF/CSV-отчёт."},
	})
}
